text:
  & .sync-option {
    padding: var(--hub-sync-list-option-padding);
    gap: var(--hub-sync-list-option-gap);
    line-height: normal;

    &:nth-child(even) {
      background-color: var(--color-neutral-lower);
    }

    & span {
      overflow: hidden;
      text-overflow: ellipsis;
      color: var(--color-text-base);
      font-weight: 400;
    }

    &:has(input:disabled) {
      pointer-events: none;

      & span {
        color: var(--color-text-muted);
      }
    }
  }
}
